      const passwordError = document.getElementById('password-error');
      const errorBanner = document.getElementById('errorBanner');
      const btn = document.getElementById('loginBtn');

      let valid = true;

      // Reset states
      emailInput.classList.remove('error-state');
      passwordInput.classList.remove('error-state');
      emailError.classList.remove('visible');
      passwordError.classList.remove('visible');
      errorBanner.classList.remove('visible');

      // Validate email
      const emailVal = emailInput.value.trim();
      if (!emailVal || (!emailVal.includes('@') && !/^\+?\d{7,15}$/.test(emailVal.replace(/[\s\-()]/g, '')))) {
        emailInput.classList.add('error-state');
        emailError.classList.add('visible');
        valid = false;
      }

      // Validate password
      const passVal = passwordInput.value;
      if (!passVal || passVal.length < 4 || passVal.length > 60) {
        passwordInput.classList.add('error-state');
        passwordError.classList.add('visible');
        valid = false;
      }

      if (!valid) {
        emailInput.classList.contains('error-state') ? emailInput.focus() : passwordInput.focus();
