      if (val && !val.includes('@') && !/^\+?\d{7,15}$/.test(val.replace(/[\s\-()]/g, ''))) {
        this.classList.add('error-state');
        error.classList.add('visible');
      } else if (val) {
        this.classList.remove('error-state');
        error.classList.remove('visible');
